import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

// Simplified IStatus and Status for the example's self-contained compilation
interface IStatus {
    int ERROR = 4;
    String getMessage();
}

class Status implements IStatus {
    private int severity;
    private String plugin;
    private String message;
    public Status(int severity, String plugin, String message) {
        this.severity = severity;
        this.plugin = plugin;
        this.message = message;
    }
    @Override public String getMessage() { return message; }
    @Override public String toString() { return "Status(" + message + ")"; }
}

public class Example {
    public void methodWithStream() {
        List<IStatus> errors = new ArrayList<>();
        errors.add(new Status(IStatus.ERROR, "pluginId", "Error one"));
        errors.add(new Status(IStatus.ERROR, "pluginId", "Error two"));
        // This is the pattern to match: Stream.toString() is usually not desired
        String streamDescription = errors.stream().toString();
        System.out.println(streamDescription);
    }
}

